/**
 * The questions before the account (onboarding v2, uiux 2026-10-21 spec
 * §4.2–4.7): the language learnt, the language spoken, why (up to three), where words are
 * met, the plan worked out from them, and the learner's own first word, then
 * the account sheet. Each step is its own address and history entry, so Back
 * and Android's back key go one question back and a reload keeps the
 * answers (they live in the draft, `introDraft.ts`). Nothing here talks to
 * the network except `GET /config` for the plan's measured numbers and the
 * anonymous count of each screen reached (`introSteps.ts`: the screen's
 * name and the platform, never an answer), and nothing here runs AI: that
 * waits for the account.
 */
const STEPS = ['learn', 'speak', 'why', 'where', 'plan', 'word'] as const;
type Step = (typeof STEPS)[number];

/** Steps that show the five-segment progress (the word step is past it). */
const PROGRESS_STEPS = 5;

/** A pick advances by itself after this long, so its check is seen; less under reduced motion. */
const PICK_ADVANCE_MS = 260;
const PICK_ADVANCE_REDUCED_MS = 60;
/** The word step's field takes focus once the step has arrived (--dur-step). */
const STEP_MS = 280;
/** The plan's numbers count to their new value in --dur-count. */
const COUNT_MS = 700;
/** The plan lists at most this many ways to save words. */
const MAX_ROUTES = 3;
/** With nothing ticked, the plan suggests the two ways that suit anyone. */
const DEFAULT_ROUTES: readonly Where[] = ['web', 'class'];

interface IntroState {
  from?: unknown;
  /** The account sheet open over the word step: for the word, or for the plan alone. */
  sheet?: unknown;
}

function isStep(value: string | undefined): value is Step {
  return (STEPS as readonly string[]).includes(value ?? '');
}

/** The first step whose answer is missing, which every later step needs. */
function firstMissing(draft: IntroDraft): Step | undefined {
  if (draft.target === undefined) return 'learn';
  if (draft.meaning === undefined) return 'speak';
  return undefined;
}

export function IntroQuestions(): React.JSX.Element {
  const { step: param } = useParams();
  const location = useLocation();
  const state = (location.state as IntroState | null) ?? {};
  const from = state.from;
  const [draft, setDraft] = useState<IntroDraft>(() => readDraft());
  const update = (change: DraftChange): IntroDraft => {
    const next = saveDraft(change);
    setDraft(next);
    return next;
  };

  if (!isStep(param)) return <Navigate to="/intro" replace state={{ from }} />;
  const missing = firstMissing(draft);
  if (missing !== undefined && STEPS.indexOf(param) > STEPS.indexOf(missing)) {
    return <Navigate to={`/intro/${missing}`} replace state={{ from }} />;
  }
  return <StepScreen key={param} step={param} draft={draft} update={update} from={from} />;
}

function StepScreen({
  step,
  draft,
  update,
  from,
}: {
  step: Step;
  draft: IntroDraft;
  update: (change: DraftChange) => IntroDraft;
  from: unknown;
}): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  // Back arrives as a pop: the step comes in from the other side.
  const back = useNavigationType() === NavigationType.Pop;
  const heading = useRef<HTMLHeadingElement>(null);
  const index = STEPS.indexOf(step);

  useEffect(() => {
    heading.current?.focus({ preventScroll: true });
  }, []);
  useEffect(() => {
    countIntroStep(step);
  }, [step]);

  const go = (next: Step): void => {
    void navigate(`/intro/${next}`, { state: { from } });
  };
  const goBack = (): void => {
    // A step opened directly (a reload after the app was closed) has nothing
    // of ours behind it: Back goes to the step before, not out of the app.
    if (location.key === 'default') {
      void navigate(index === 0 ? '/intro' : `/intro/${STEPS[index - 1] ?? 'learn'}`, {
        replace: true,
        state: { from },
      });
      return;
    }
    void navigate(-1);
  };
  // Once a one-tap answer is on its way to the next step, a second tap in
  // the 260 ms before it leaves changes nothing.
  const leaving = useRef(false);
  /** A one-tap answer: the check pops, the phone ticks, and the next step follows. */
  const pick = (answer: () => void, next: Step): void => {
    if (leaving.current) return;
    leaving.current = true;
    answer();
    advanceAfterPick(next);
  };
  const advanceAfterPick = (next: Step): void => {
    platform.haptics.select();
    window.setTimeout(
      () => {
        go(next);
      },
      prefersReducedMotion() ? PICK_ADVANCE_REDUCED_MS : PICK_ADVANCE_MS,
    );
  };

  return (
    <main className={cx(styles.screen, back ? styles.enterBack : styles.enter)}>
      <div className={styles.head}>
        <button type="button" className={styles.back} aria-label={t('action.back')} onClick={goBack}>
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        {index < PROGRESS_STEPS ? (
          <div
            className={styles.steps}
            role="progressbar"
            aria-label={t('onb.step', { n: index + 1 })}
            aria-valuenow={index + 1}
            aria-valuemin={1}
            aria-valuemax={PROGRESS_STEPS}
          >
            {Array.from({ length: PROGRESS_STEPS }, (_, segment) => (
              <i key={segment} className={cx(segment <= index && styles.stepOn)} />
            ))}
          </div>
        ) : (
          <span />
        )}
        <span />
      </div>
      {step === 'learn' && (
        <Scroll>
          <h1 ref={heading} className={styles.title} tabIndex={-1}>
            {t('onboarding.targetLang')}
          </h1>
          <p className={styles.lead}>{t('onboarding.targetLangLead')}</p>
          <LanguagePicker
            label={t('onboarding.targetLang')}
            codes={TARGET_LANGUAGES}
            value={draft.target}
            onPick={(target) => {
              pick(() => update({ target }), 'speak');
            }}
          />
        </Scroll>
      )}
      {step === 'speak' && draft.target !== undefined && (
        <Scroll>
          <span className={styles.pair}>
            {t('onb.speak.learning', { language: LANGUAGE_NAMES[draft.target] })}
          </span>
          <h1 ref={heading} className={styles.title} tabIndex={-1}>
            {t('onb.speak.title')}
          </h1>
          <p className={styles.lead}>{t('onb.speak.lead')}</p>
          <LanguagePicker
            label={t('onb.speak.title')}
            codes={MEANING_LANGUAGES}
            value={draft.meaning}
            markDevice
            onPick={(meaning) => {
              pick(() => update({ meaning }), 'why');
            }}
          />
        </Scroll>
      )}
      {step === 'why' && (
        <>
          <Scroll>
            <h1 ref={heading} className={styles.title} tabIndex={-1}>
              {t('onb.why.title')}
            </h1>
            <p className={styles.lead}>{t('onb.why.lead', { max: MAX_WHY })}</p>
            <WhyTiles
              value={draft.why}
              onToggle={(why) => {
                const picked = draft.why.includes(why);
                if (!picked && draft.why.length >= MAX_WHY) return false;
                platform.haptics.select();
                // A change of reasons starts the plan on their own default minutes.
                update({
                  why: picked ? draft.why.filter((one) => one !== why) : [...draft.why, why],
                  minutes: undefined,
                });
                return true;
              }}
            />
          </Scroll>
          <div className={styles.foot}>
            <button
              type="button"
              className={styles.primary}
              disabled={draft.why.length === 0}
              onClick={() => {
                go('where');
              }}
            >
              {t('onb.continue')}
            </button>
          </div>
        </>
      )}
      {step === 'where' && (
        <>
          <Scroll>
            <h1 ref={heading} className={styles.title} tabIndex={-1}>
              {t('onb.where.title')}
            </h1>
            <p className={styles.lead}>{t('onb.where.lead')}</p>
            <WhereRows
              value={draft.where}
              onToggle={(place) => {
                platform.haptics.select();
                update({
                  where: draft.where.includes(place)
                    ? draft.where.filter((one) => one !== place)
                    : [...draft.where, place],
                });
              }}
            />
          </Scroll>
          <div className={styles.foot}>
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                go('plan');
              }}
            >
              {draft.where.length > 0 ? t('onb.continue') : t('onb.skip')}
            </button>
          </div>
        </>
      )}
      {step === 'plan' && draft.target !== undefined && (
        <PlanStep
          heading={heading}
          draft={draft}
          target={draft.target}
          onMinutes={(minutes) => {
            platform.haptics.select();
            update({ minutes });
          }}
          onStart={() => {
            // The plan the learner saw is the plan that is kept.
            update({ minutes: planMinutes(draft.minutes, draft.why) });
            go('word');
          }}
        />
      )}
      {step === 'word' && draft.target !== undefined && (
        <WordStep heading={heading} draft={draft} target={draft.target} update={update} from={from} />
      )}
    </main>
  );
}

/** The scrolling column under the step's head. */
function Scroll({ children }: { children: React.ReactNode }): React.JSX.Element {
  return (
    <div className={styles.scroll}>
      <div className={styles.col}>{children}</div>
    </div>
  );
}

const WHY_ICONS: Readonly<Record<Why, IconName>> = {
  exam: 'exam',
  work: 'briefcase',
  move: 'moveAbroad',
  read: 'bookOpen',
  travel: 'plane',
  me: 'heart',
};

/**
 * Six reasons, up to MAX_WHY of them (spec §4.3; owner, 22 Oct 2026):
 * toggle buttons, like the places. Once MAX_WHY are picked the others rest
 * dimmed; a tap on one is refused gently, with a nudge and a line that says
 * how to pick it instead, never a silent nothing.
 */
function WhyTiles({
  value,
  onToggle,
}: {
  value: readonly Why[];
  /** Answers false when the pick was refused because MAX_WHY are already picked. */
  onToggle: (why: Why) => boolean;
}): React.JSX.Element {
  // The tile a refused tap landed on, and a count so a second refusal nudges again.
  const [refused, setRefused] = useState<{ why: Why; n: number } | undefined>(undefined);
  const full = value.length >= MAX_WHY;
  const line =
    refused !== undefined && full
      ? t('onb.why.full', { max: MAX_WHY })
      : value.length > 0
        ? t('onb.why.count', { n: value.length, max: MAX_WHY })
        : '';
  return (
    <>
      <div className={styles.whyGrid} role="group" aria-label={t('onb.why.title')}>
        {WHY_CHOICES.map((why) => {
          const on = value.includes(why);
          const resting = full && !on;
          return (
            <button
              key={refused?.why === why ? `${why}-${String(refused.n)}` : why}
              type="button"
              aria-pressed={on}
              aria-disabled={resting || undefined}
              aria-describedby="why-count"
              className={cx(
                styles.tile,
                styles.why,
                on && styles.tileOn,
                resting && styles.tileRest,
                refused?.why === why && styles.tileRefused,
              )}
              onClick={() => {
                if (onToggle(why)) setRefused(undefined);
                else setRefused((was) => ({ why, n: (was?.n ?? 0) + 1 }));
              }}
            >
              <span className={styles.whyIcon} aria-hidden="true">
                <Icon name={WHY_ICONS[why]} size={22} weight={2} />
              </span>
              <span className={styles.whyText}>{t(`onb.why.${why}`)}</span>
              <span className={cx(styles.check, styles.whyCheck)} aria-hidden="true">
                <Icon name="check" size={14} weight={2.6} />
              </span>
            </button>
          );
        })}
      </div>
      <p
        id="why-count"
        className={cx(styles.pickLine, refused !== undefined && full && styles.pickLineFull)}
        role="status"
      >
        {line}
      </p>
    </>
  );
}

