/** A number that counts to its new value when it changes (--dur-count); at once under reduced motion. */
function useCounted(value: number): number {
  const [shown, setShown] = useState(value);
  const last = useRef(value);
  useEffect(() => {
    const from = last.current;
    last.current = value;
    if (from === value || prefersReducedMotion()) {
      setShown(value);
      return;
    }
    const start = performance.now();
    let frame = 0;
    const step = (now: number): void => {
      const progress = Math.min(1, (now - start) / COUNT_MS);
      setShown(Math.round(from + (value - from) * (1 - (1 - progress) ** 3)));
      if (progress < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [value]);
  return shown;
}

/** Your plan (spec §4.5): the numbers from the engine, the minutes to change them, the ways in. */
function PlanStep({
  heading,
  draft,
  target,
  onMinutes,
  onStart,
}: {
  heading: React.RefObject<HTMLHeadingElement | null>;
  draft: IntroDraft;
  target: LanguageCode;
  onMinutes: (minutes: Minutes) => void;
  onStart: () => void;
}): React.JSX.Element {
  // The measured seconds a card and recall, when the server has them.
  const ensure = useConfig((s) => s.ensure);
  const measured = useConfig((s) => s.plan);
  useEffect(() => {
    ensure();
  }, [ensure]);
  const minutes = planMinutes(draft.minutes, draft.why);
  // eslint-disable-next-line react-hooks/exhaustive-deps -- `measured` changes the numbers planFor reads
  const plan = useMemo(() => planFor(minutes), [minutes, measured]);
  const [now] = useState(() => new Date());
  const date = planDate(now);
  const perDay = useCounted(plan.newPerDay);
  const total = useCounted(plan.wordsAtHorizon);
  const shownMinutes = useCounted(minutes);
  const max = plan.weekly[plan.weekly.length - 1] ?? 1;
  const routes = (draft.where.length > 0 ? draft.where : DEFAULT_ROUTES).slice(0, MAX_ROUTES);
  const selected = MINUTE_CHOICES.indexOf(minutes);
  const reason = planReason(draft.why);
  return (
    <>
      <Scroll>
        <h1 ref={heading} className={styles.title} tabIndex={-1}>
          {t('onb.plan.title')}
        </h1>
        <section
          className={styles.hero}
          aria-label={t('onb.plan.summary', {
            count: plan.newPerDay,
            minutes,
            total: plan.wordsAtHorizon,
            date,
          })}
        >
          <span className={styles.pill}>
            {reason.more > 0
              ? t('onb.plan.pillMore', {
                  language: LANGUAGE_NAMES[target],
                  why: t(`onb.plan.for.${reason.lead}`),
                  more: reason.more,
                })
              : t('onb.plan.pill', {
                  language: LANGUAGE_NAMES[target],
                  why: t(`onb.plan.for.${reason.lead}`),
                })}
          </span>
          <div className={styles.big} aria-hidden="true">
            <b>{perDay}</b>
            <span>{plan.newPerDay === 1 ? t('onb.plan.wordsOne') : t('onb.plan.words')}</span>
          </div>
          <div className={styles.stats} aria-hidden="true">
            <div>
              <b>{t('onb.plan.minutes', { n: shownMinutes })}</b>
              <span>{t('onb.plan.minutesSub')}</span>
            </div>
            <div>
              <b>{t('onb.plan.total', { n: total.toLocaleString() })}</b>
              <span>{t('onb.plan.by', { date })}</span>
            </div>
          </div>
          <div className={styles.growth} aria-hidden="true">
            {plan.weekly.map((words, week) => (
              <i
                key={week}
                style={
                  {
                    height: `${String(8 + (92 * words) / max)}%`,
                    '--i': week,
                  } as React.CSSProperties
                }
              />
            ))}
          </div>
          <div className={styles.axis} aria-hidden="true">
            <span>{t('onb.plan.axisToday')}</span>
            <span>{t('onb.plan.axis1')}</span>
            <span>{t('onb.plan.axis2')}</span>
            <span>{t('onb.plan.axis3')}</span>
          </div>
        </section>
        <p className={styles.label} id="plan-time">
          {t('onb.plan.time')}
        </p>
        <div className={styles.seg} role="radiogroup" aria-labelledby="plan-time">
          <span
            className={styles.thumb}
            style={{ '--idx': Math.max(0, selected) } as React.CSSProperties}
            aria-hidden="true"
          />
          {MINUTE_CHOICES.map((choice) => (
            <button
              key={choice}
              type="button"
              role="radio"
              aria-checked={choice === minutes}
              onClick={() => {
                if (choice !== minutes) onMinutes(choice);
              }}
            >
              {t('onb.plan.min', { n: choice })}
            </button>
          ))}
        </div>
        <p className={styles.note}>{t('onb.plan.note', { days: intervalDays() })}</p>
        <h2 className={styles.h2}>{t('onb.plan.routes')}</h2>
        <p className={cx(styles.lead, styles.leadSmall)}>{t('onb.plan.routesLead')}</p>
        <div className={styles.list}>
          {routes.map((place) => (
            <Route key={place} place={place} />
          ))}
        </div>
        <div className={styles.endSpace} />
      </Scroll>
      <div className={cx(styles.foot, styles.footFade)}>
        <button type="button" className={styles.primary} onClick={onStart}>
          {t('onb.plan.start')}
        </button>
      </div>
    </>
  );
}

/** One way to save words, for the plan: information only, no navigation away mid-flow. */
function Route({ place }: { place: Where }): React.JSX.Element {
  const content = ((): { logo: React.ReactNode; title: string; line: React.ReactNode } => {
    switch (place) {
      case 'books':
        return {
          logo: (
            <span className={styles.logo}>
              <img src={kindleLogo} alt="" width={44} height={44} />
            </span>
          ),
          title: t('onb.route.kindle'),
          line: t('onb.route.kindleLine'),
        };
      case 'web':
        return {
          logo: (
            <span className={cx(styles.logo, styles.logoBrowsers)}>
              <img src={chromeLogo} alt="" width={18} height={18} />
              <img src={edgeLogo} alt="" width={18} height={18} />
              <img src={firefoxLogo} alt="" width={18} height={18} />
            </span>
          ),
          title: t('onb.route.web'),
          line: t('onb.route.webLine'),
        };
      case 'video': {
        const [before = '', middle = '', after = ''] = t('onb.route.watchLine', {
          mac: '\u0000',
          pc: '\u0000',
        }).split('\u0000');
        return {
          logo: (
            <span className={cx(styles.logo, styles.logoPlain)}>
              <Icon name="computer" size={22} weight={2} />
            </span>
          ),
          title: t('onb.route.watch'),
          line: (
            <>
              {before}
              <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, true)}</kbd>
              {middle}
              <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, false)}</kbd>
              {after}
            </>
          ),
        };
      }
      case 'class':
        return {
          logo: (
            <span className={cx(styles.logo, styles.logoPlain)}>
              <Icon name="list" size={22} weight={2} />
            </span>
          ),
          title: t('onb.route.list'),
          line: t('onb.route.listLine'),
        };
      case 'ai':
        return { logo: <AssistantMarks />, title: t('onb.route.ai'), line: t('onb.route.aiLine') };
    }
  })();
  return (
    <div className={styles.route}>
      {content.logo}
      <span className={styles.rowText}>
        <b>{content.title}</b>
        <span>{content.line}</span>
      </span>
    </div>
  );
}

/**
 * The script a word is written in, when it cannot be the notebook's language
 * ("Persian or Arabic"): the two languages the list would put first among
 * those that write it. Undefined when it fits, or when there are no letters
 * to tell.
 */
function scriptMismatch(word: string, target: LanguageCode): string | undefined {
  if (!canBeCard(word)) return undefined;
  const script = scriptOf(word);
  if (script === 'unknown' || couldBe(word, [target]).length > 0) return undefined;
  // Named by the languages that write it, as the language list would order them.
  const order = [...PINNED_LANGUAGES, ...TARGET_LANGUAGES];
  const writers = languagesInScript(script)
    .filter((code) => order.includes(code))
    .sort((a, b) => order.indexOf(a) - order.indexOf(b));
  const [first, second] = writers;
  if (first === undefined) return undefined;
  const name = (code: LanguageCode): string => LANGUAGE_INFO[code].name;
  return second === undefined ? name(first) : t('onb.word.scriptOr', { a: name(first), b: name(second) });
}

/** Your word (spec §4.6), and the account sheet it opens (§4.7). */
function WordStep({
  heading,
  draft,
  target,
  update,
  from,
}: {
  heading: React.RefObject<HTMLHeadingElement | null>;
  draft: IntroDraft;
  target: LanguageCode;
  update: (change: DraftChange) => IntroDraft;
  from: unknown;
}): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const sheet = (location.state as IntroState | null)?.sheet;
  const open: AccountSheetKind | undefined = sheet === 'word' || sheet === 'plan' ? sheet : undefined;
  const [text, setText] = useState(draft.word ?? '');
  const input = useRef<HTMLInputElement>(null);
  const ready = canBeCard(text);
  const mismatch = scriptMismatch(text, target);
  // With the keyboard up the column is short: a note that just appeared is
  // brought into sight rather than left under the buttons.
  const warn = useRef<HTMLParagraphElement>(null);
  const warned = mismatch !== undefined;
  useEffect(() => {
    const note = warn.current;
    if (!warned || note === null || typeof note.scrollIntoView !== 'function') return;
    note.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }, [warned]);
  // A link from the site's Anki and Quizlet pages asked for the paste box.
  const wantsPaste = typeof from === 'string' && from.includes('import=paste');

  // Typing is this step's whole job: the field takes focus once the step has arrived.
  useEffect(() => {
    if (open !== undefined) return;
    const timer = window.setTimeout(() => {
      input.current?.focus({ preventScroll: true });
    }, STEP_MS);
    return () => {
      window.clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- once, on arrival
  }, []);

  /** The sheet is its own history entry, so Android's back key closes it. */
  const openSheet = (kind: AccountSheetKind): void => {
    void navigate(location.pathname, { state: { from, sheet: kind } });
  };
  const make = (): void => {
    if (!ready) return;
    update({ word: normalizeIntroWord(text) });
    openSheet('word');
  };

  return (
    <>
      <Scroll>
        <h1 ref={heading} className={styles.title} tabIndex={-1}>
          {t('onb.word.title')}
        </h1>
        <p className={styles.lead}>{t('onb.word.lead')}</p>
        <form
          className={styles.wordField}
          onSubmit={(event) => {
            event.preventDefault();
            make();
          }}
          noValidate
        >
          <label htmlFor="intro-word" className="sr-only">
            {t('onb.word.placeholder')}
          </label>
          <input
            ref={input}
            id="intro-word"
            value={text}
            dir="auto"
            lang={target}
            placeholder={t('onb.word.placeholder')}
            autoComplete="off"
            autoCapitalize="off"
            autoCorrect="off"
            spellCheck={false}
            enterKeyHint="go"
            aria-describedby={
              mismatch === undefined ? 'intro-word-helper' : 'intro-word-helper intro-word-script'
            }
            onChange={(event) => {
              // Cut at the headword limit by characters, never mid-letter.
              const chars = Array.from(event.target.value);
              setText(
                chars.length > HEADWORD_MAX ? chars.slice(0, HEADWORD_MAX).join('') : event.target.value,
              );
            }}
          />
        </form>
        <p className={styles.helper} id="intro-word-helper">
          <Icon name="sparkles" size={16} weight={2} />
          {t('onb.word.helper')}
        </p>
        {mismatch !== undefined && (
          <p ref={warn} className={styles.warn} id="intro-word-script" role="status">
            {t('onb.word.script', { script: mismatch, language: LANGUAGE_NAMES[target] })}
          </p>
        )}
      </Scroll>
      <div className={styles.foot}>
        <button type="button" className={styles.primary} disabled={!ready} onClick={make}>
          {t('onb.word.make')}
        </button>
        {wantsPaste && (
          <button
            type="button"
            className={styles.quiet}
            onClick={() => {
              update({ word: undefined });
              openSheet('plan');
            }}
          >
            {t('onb.word.paste')}
          </button>
        )}
        <button
          type="button"
          className={styles.quiet}
          onClick={() => {
            update({ word: undefined });
            openSheet('plan');
          }}
        >
          {t('onb.word.later')}
        </button>
      </div>
      {open !== undefined && (
        <AccountSheet
          kind={open}
          word={open === 'word' ? draft.word : undefined}
          onClose={() => {
            void navigate(-1);
          }}
        />
      )}
    </>
  );
}
