import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { t } from '@/i18n/index.js';
import { SignIn } from '@/features/auth/SignIn.js';
import { countIntroStep } from './introSteps.js';
import styles from './AccountSheet.module.css';

/** For the learner's word ("Make my card"), or for the plan alone ("I'll add words later"). */
export type AccountSheetKind = 'word' | 'plan';

/**
 * The account, asked for at the moment it buys something (onboarding v2
 * spec §4.7): after the questions and the learner's own word, just before
 * AI runs, which keeps "no AI before an account". It is the existing
 * `SignIn` in a sheet frame: Google's web redirect, Apple's hidden-address
 * step and e-mail verification all stay as they are. Once the account
 * exists the intro's own gate sends the learner on to the first card.
 *
 * A bottom sheet on a phone, a dialog from `medium` up. It traps focus,
 * returns it on close, and Escape or the scrim closes it.
 */
export function AccountSheet({
  kind,
  word,
  onClose,
}: {
  kind: AccountSheetKind;
  word: string | undefined;
  onClose: () => void;
}): React.JSX.Element {
  const panel = useRef<HTMLDivElement>(null);
  const close = useRef(onClose);
  useEffect(() => {
    close.current = onClose;
  });

  useEffect(() => {
    countIntroStep('account');
  }, []);

  useEffect(() => {
    const restore = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close.current();
        return;
      }
      if (event.key !== 'Tab' || panel.current === null) return;
      // Focus stays inside the sheet while it is open.
      const focusable = [
        ...panel.current.querySelectorAll<HTMLElement>(
          'button:not([disabled]), a[href], input:not([disabled]), [tabindex]:not([tabindex="-1"])',
        ),
      ];
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (first === undefined || last === undefined) return;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.body.style.overflow = overflow;
      restore?.focus({ preventScroll: true });
    };
  }, []);

  const forWord = kind === 'word' && word !== undefined;
  return createPortal(
    <div className={styles.layer}>
      <div className={styles.scrim} onClick={onClose} aria-hidden="true" />
      <div
        ref={panel}
        className={styles.sheet}
        role="dialog"
        aria-modal="true"
        aria-label={forWord ? t('onb.acc.title') : t('onb.acc.titlePlan')}
      >
        <div className={styles.grab} aria-hidden="true" />
        <SignIn
          frame="sheet"
          title={forWord ? t('onb.acc.title') : t('onb.acc.titlePlan')}
          lead={forWord ? t('onb.acc.lead') : t('onb.acc.leadPlan')}
          top={
            forWord ? (
              <span className={styles.chip}>
                <bdi dir="auto">{word}</bdi>
                <span className={styles.chipNew}>{t('onb.s1.new')}</span>
              </span>
            ) : undefined
          }
        />
      </div>
    </div>,
    document.body,
  );
}
